inputs.chosen/workflow.yaml:
apiVersion: argoproj.io/v1alpha1
kind: Workflow
metadata: {name: completion, namespace: argo}
spec:
  entrypoint: main
  templates:
    - name: main
      inputs: {parameters: [{name: message, default: ready}]}
      container: {image: alpine, args: ["中🐌", "{{inputs.parameters.me}}"], imagePullPolcy: Always}
    - name: other
      inputs: {parameters: [{name: message, default: unrelated}]}
      container: {image: alpine, args: ["{{inputs.parameters.message}}"]}

